package com.project.shopApp.dtos;import com.fasterxml.jackson.annotation.JsonProperty;import jakarta.validation.constraints.Min;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Size;import lombok.*;@Data@Getter@Setter@Builder@AllArgsConstructor@NoArgsConstructorpublic class OrderDetailsDTO {    @JsonProperty("order_id")    @Min(value = 1, message = "Order's ID must be > 0")    private Long orderID;    @Min(value = 1, message = "Product's ID must be > 0")    @JsonProperty("product_id")    private Long productID;    @Min(value = 0,message = "Prive must be > 0")    private Float price;    @Min(value = 1, message = "Number of products must be >= 1")    @JsonProperty("number_of_product")    private Long numberOfProduct;    @Min(value = 0, message = "Total money must be greater or equal to 0")    @JsonProperty("total_money")    private Float totalMoney;    private String color;}